// English-only drop-in for `bip39-mnemonic/wordlist`, substituted at BUNDLE TIME
// by scripts/bare-imports.js. Nothing in the app requires this file directly.
//
// WHY IT EXISTS. bip39-mnemonic ships twelve wordlists plus a 578 KB reverse
// lookup table used only to guess which language a phrase is written in. The
// worklet bundle is not tree-shaken, so an unreachable `require` costs full size,
// and all thirteen files landed in it: 841 KB for a feature we never use. Same
// shape as the tinyld language table dropped in PR #82.
//
// WHY ENGLISH ONLY IS CORRECT, not just cheaper. PearList only ever MINTS English
// phrases - @peerloom/device-link's `generateMnemonic` takes bip39's `english`
// default and never passes a language - so it only ever needs to READ English.
// The cost is that a phrase generated by some OTHER app in another language will
// not validate here. That is a real limit and it is stated in DECISIONS.md rather
// than left to be discovered during a restore.
//
// UPSTREAM PARITY. Only `loadWordlist` and `detectLanguage` are replaced; every
// line of BIP39 arithmetic (checksum, uint11 packing, PBKDF2 seed derivation)
// stays upstream's, so there is no fork of the cryptography to keep in step. The
// wordlist itself is the frozen BIP39 English list, which cannot change without
// invalidating every phrase ever generated - and test/bundleTrim.test.js asserts
// our copy still matches the installed package's, so drift cannot pass silently.

const english = require('./bip39-english.json')

// Set for lookup: `detectLanguage` runs over every word of a typed phrase, and
// indexOf over 2048 entries per word is the one hot path here.
const englishSet = new Set(english)

module.exports = { loadWordlist, detectLanguage }

function loadWordlist (language) {
  if (language === 'english') return english

  // Upstream's message, kept verbatim: a caller that asks for another language is
  // a bug rather than a user error, and matching the string keeps any test or log
  // written against upstream still meaningful.
  throw new Error('Unknown language: ' + language)
}

// Upstream returns the language a phrase is written in, or null when a word
// belongs to none of them. With one language the answer is binary. Returning null
// makes `mnemonicToEntropy` throw 'Language not recognised', which
// `validateMnemonic` already catches and turns into false - so a non-English
// phrase is REJECTED, never misread.
function detectLanguage (words) {
  if (!words || words.length === 0) return null

  for (const word of words) {
    if (!englishSet.has(word)) return null
  }

  return 'english'
}
